   "se": "train",
   "name": "",
   "text": "夏の盛り、車窓の海がまぶしく光った。三年ぶりに帰る星見町は、潮の匂いまで懐かしく、湊は小さく息を吐いた。窓に額を寄せると、ガラス越しの日差しがまぶたの裏まで温かく、長い移動の疲れがほどけていくようだった。"
