   "text": "閉館の鐘が鳴り、二人は閲覧室を後にした。振り返ると、白い一角が月明かりに淡く光っていた。それは未完の印ではなく、約束の色だった。言葉にならない思いだけが、胸の奥で静かに熱を持ち続けていた。"
